import os, sys
sys.path.insert(0, os.path.join(os.path.dirname(os.path.abspath(__file__)), '..', '..', 'engenharia-reversa'))
from gen_docs import fazer, leia, cadeia, prova_save, resultado_pt_en

N = 298
R = [('sco_prm_create_schedule', 'ScoPrm::create_schedule', '0x7f0e80', 'sco_prm.cpp', 'thiscall, ret 0x10', 'regra: 38 rodadas (12 clubes): 33 em três turnos de 29/7 a 7/4 do ano seguinte, aos sábados com a faixa de TV (5, 2, 2) na maioria delas e três no meio da semana (17/10, 29/11, 2/1), o bloco do fim do ano de duas rodadas escolhido pelo dia em que cai a 21a; depois a divisão em dois grupos de seis (fases 0 e 1: cinco sábados de 14/4 a 12/5); em 1999 (10 clubes, 4 turnos) 36 rodadas e nenhuma divisão', 'rule: 38 rounds (12 clubs): 33 in three rounds from 29/7 to 7/4 of the next year, Saturdays with the TV slot (5, 2, 2) in most of them and three midweek (17/10, 29/11, 2/1), the year-end block of two rounds chosen by the day the 21st falls on; then the split into two groups of six (stages 0 and 1: five Saturdays from 14/4 to 12/5); in 1999 (10 clubs, 4 rounds) 36 rounds and no split'), ('sco_prm_start_new_season', 'ScoPrm::start_new_season', '0x7f2a70', 'sco_prm.cpp', 'thiscall, ret 0', 'regra: a virada escocesa começa pela Premier: sobe e desce entre as divisões; em 1999 Elgin City e Peterhead entram na Third (a ampliação de 2000); a Premier passa ao ano seguinte e refaz regras, tabela, jogos e ordem; o teto de divisão dos clubes da Second e da Third; a virada da First, da Second e da Third; as posições previstas, as expectativas da diretoria e a renovação dos árbitros', 'rule: the Scottish turnover is led by the Premier: promotion and relegation between the divisions; in 1999 Elgin City and Peterhead join the Third (the 2000 expansion); the Premier moves to the next year and rebuilds the rules, the table, the fixtures and the order; the division tier of the Second and Third Division clubs is capped; the First, the Second and the Third turn over; the predicted positions, the board expectations and the renewal of the referees'), ('sco_prm_update_for_date', 'ScoPrm::update_for_date', '0x7f2d20', 'sco_prm.cpp', 'thiscall, ret 8', 'regra: na temporada de 3 turnos, num dia com resultados, quando todos os clubes jogaram 33 vezes a Premier se divide (split); depois a atualização do dia da liga', 'rule: in the season of 3 rounds, on a day with results, when every club has played 33 games the Premier splits; then the league day update'), ('sco_prm_create_split_stages', 'ScoPrm::create_split_stages', '0x7f2d90', 'sco_prm.cpp', 'thiscall, ret 0', 'regra: o split: os seis primeiros e os seis últimos (do último para cima) jogam mais cinco rodadas entre si; depois a liga segue em 4 turnos com a comparação que mantém as duas metades separadas na tabela', 'rule: the split: the top six and the bottom six (from the last up) play five more rounds among themselves; then the league goes on in 4 rounds with the compare that keeps the two halves apart in the table'), ('construct_sco_lge_cup', 'ScoLgeCup::ScoLgeCup', '0x7ef9e0', 'sco_lge_cup.cpp', 'thiscall, ret 8', 'regra: a Copa da Liga escocesa nasce com 40 vagas vazias, 5 reservas e 3 substituições, a disciplina das copas escocesas (0x19) e um fundo de prêmios de 1 milhão; os inscritos e as posições previstas só vêm quando a temporada começa', 'rule: the Scottish League Cup is created with 40 empty places, 5 substitutes and 3 substitutions, the discipline rule of the Scottish cups (0x19) and a prize fund of 1,000,000; the entrants and the predicted positions only come when the season starts'), ('sco_lge_cup_create_round_table', 'ScoLgeCup::create_round_table', '0x7efcb0', 'sco_lge_cup.cpp', 'thiscall, ret 0x10', 'regra: 6 rodadas de jogo único: 1ª sorteada em 10/7 e jogada em 31/7, 2ª 1/8 e 17/8, 3ª 19/8 e 22/9, quartas 23/9 e 1/12, semifinal 2/12 e 16/2 em campo neutro, final sorteada em 17/2 e jogada em 19/3 no estádio nacional; os clubes nas copas europeias só entram na 3ª (de 2000 em diante: 2b + 20 na 1ª rodada, (16 - b) x 2 na 2ª); categoria 4 nas três primeiras, 6 depois; sem prêmio por rodada', 'rule: 6 single-match rounds: the 1st drawn on 10/7 and played on 31/7, the 2nd 1/8 and 17/8, the 3rd 19/8 and 22/9, quarter-finals 23/9 and 1/12, semi-finals 2/12 and 16/2 at a neutral ground, the final drawn on 17/2 and played on 19/3 at the national stadium; the clubs in the European cups only enter in the 3rd (from 2000: 2b + 20 in the 1st round, (16 - b) x 2 in the 2nd); category 4 in the first three, 6 after; no prize per round'), ('sco_lge_cup_update_for_date', 'ScoLgeCup::update_for_date', '0x7f0230', 'sco_lge_cup.cpp', 'thiscall, ret 8', 'regra: a Copa da Liga escocesa é refeita uma vez por temporada, no primeiro dia com resultados em que o ano do jogo chega ao da copa: libera as tabelas velhas e monta os inscritos, as rodadas, a árvore de confrontos e as posições previstas; depois, todo dia, a atualização da copa (sorteios e jogos nas datas da tabela)', 'rule: the Scottish League Cup is rebuilt once per season, on the first day with results when the game year reaches the cup year: the old tables are freed and the entrants, the rounds, the fixture tree and the predicted positions are built; then, every day, the cup update (draws and matches on the table dates)'), ('sco_lge_cup_start_new_season', 'ScoLgeCup::start_new_season', '0x7f0930', 'sco_lge_cup.cpp', 'thiscall, ret 0', 'regra: na virada a Copa da Liga escocesa libera os times, as rodadas e os confrontos da edição passada, arquiva as estatísticas, passa ao ano seguinte e volta a 40 vagas vazias (os inscritos vêm quando a temporada começa); refaz as rodadas e a árvore de confrontos', "rule: at the turnover the Scottish League Cup frees last edition's teams, rounds and ties, archives the statistics, moves to the next year and goes back to 40 empty places (the entrants come when the season starts); it rebuilds the rounds and the fixture tree"), ('wel_lge_cup_create_table', 'WelLgeCup::create_table', '0x926700', 'wel_lge_cup.cpp', 'thiscall, ret 0', 'regra: a própria copa é o primeiro grupo, de 3 clubes: o primeiro de cada linha do bolo de inscritos (a coluna do grupo 0), tirados do bolo; depois a notícia do sorteio do grupo', "rule: the cup itself is the first group, of 3 clubs: the first of each row of the entrant pool (group 0's column), taken out of the pool; then the group draw news"), ('wel_lge_cup_set_up_rules', 'WelLgeCup::set_up_rules', '0x926800', 'wel_lge_cup.cpp', 'thiscall, ret 0', 'regra: os grupos jogam 2 turnos, 3 pontos por vitória e 1 por empate, categoria 4; o primeiro de cada grupo passa; desempate pelos códigos 4, 1 e 2 (confronto direto, saldo, gols pró [inferência]); fundo de prêmios de 100 mil', 'rule: the groups play 2 rounds, 3 points for a win and 1 for a draw, category 4; the winner of each group goes through; tie-breaks codes 4, 1 and 2 (head-to-head, goal difference, goals for [inference]); a prize fund of 100,000'), ('wel_lge_cup_advance_stage', 'WelLgeCup::advance_stage', '0x926a70', 'wel_lge_cup.cpp', 'thiscall, ret 0', 'regra: a Copa da Liga galesa passa de grupo em grupo (as fases 0 a 4 são os outros cinco grupos) e, ao chegar à fase 5, monta o mata-mata dos oito melhores', 'rule: the Welsh League Cup moves from group to group (stages 0 to 4 are the other five groups) and, on reaching stage 5, builds the knockout of the best eight'), ('wel_lge_cup_record_season_honours', 'WelLgeCup::record_season_honours', '0x926890', 'wel_lge_cup.cpp', 'thiscall, ret 0', 'regra: as honrarias da temporada da Copa da Liga galesa são as do seu mata-mata', "rule: the Welsh League Cup's season honours are those of its knockout"), ('wel_lge_cup_update_staff_records_for_status', 'WelLgeCup::update_staff_records_for_status', '0x9271e0', 'wel_lge_cup.cpp', 'thiscall, ret 0x18', 'regra: nos seis grupos, quem passa ganha o registro de classificação (peso 40) e quem sai o de eliminação nos grupos (peso 40); no mata-mata (fase 5), quem passa ganha a classificação pela rodada e quem cai o de eliminado (peso 50 a 100 em 5 rodadas); o campeão e o vice, os registros da final', 'rule: in the six groups, a club going through gets the qualification record (weight 40) and one going out the failed-to-qualify record (weight 40); in the knockout (stage 5) a club going through gets the qualification by round and one going out the knocked-out record (weight 50 to 100 over 5 rounds); the winner and the runner-up the final records'), ('wel_lge_cup_create_group_stage', 'WelLgeCup::create_group_stage', '0x926b00', 'wel_lge_cup.cpp', 'thiscall, ret 4', 'regra: o grupo g (0 a 4) tem 3 clubes, os da coluna g + 1 do bolo de inscritos, numa fase de liga própria; depois a notícia do sorteio do grupo', 'rule: group g (0 to 4) has 3 clubs, those of column g + 1 of the entrant pool, in a league stage of its own; then the group draw news'), ('wel_prm_cup_create_group_table', 'WelPrmCup::create_group_table', '0x928060', 'wel_prm_cup.cpp', 'thiscall, ret 0', 'regra: a própria copa é o primeiro grupo, de 4 clubes: os inscritos 0, 2, 4 e 6 do bolo, tirados do bolo; depois a notícia do sorteio do grupo', 'rule: the cup itself is the first group, of 4 clubs: entrants 0, 2, 4 and 6 of the pool, taken out of the pool; then the group draw news'), ('wel_prm_cup_set_up_rules', 'WelPrmCup::set_up_rules', '0x928160', 'wel_prm_cup.cpp', 'thiscall, ret 0', 'regra: os grupos jogam 2 turnos, 3 pontos por vitória e 1 por empate, categoria 4; os 2 primeiros de cada grupo passam; desempate pelos códigos 1, 2 e 4 (saldo, gols pró, confronto direto [inferência]); fundo de prêmios de 100 mil', 'rule: the groups play 2 rounds, 3 points for a win and 1 for a draw, category 4; the top 2 of each group go through; tie-breaks codes 1, 2 and 4 (goal difference, goals for, head-to-head [inference]); a prize fund of 100,000'), ('wel_prm_cup_advance_stage', 'WelPrmCup::advance_stage', '0x9283c0', 'wel_prm_cup.cpp', 'thiscall, ret 0', 'regra: a Copa Premier galesa passa do primeiro grupo ao segundo (fase 0) e, ao chegar à fase 1, monta o mata-mata dos oito', 'rule: the Welsh Premier Cup moves from the first group to the second (stage 0) and, on reaching stage 1, builds the knockout of the eight'), ('wel_prm_cup_update_staff_records_for_status', 'WelPrmCup::update_staff_records_for_status', '0x928af0', 'wel_prm_cup.cpp', 'thiscall, ret 0x18', 'regra: nos dois grupos, quem passa ganha o registro de classificação (peso 40) e quem sai o de eliminação nos grupos (peso 40); no mata-mata (fase 1), quem passa ganha a classificação pela rodada e quem cai o de eliminado (peso 50 a 100 em 3 rodadas); o campeão e o vice, os registros da final', 'rule: in the two groups, a club going through gets the qualification record (weight 40) and one going out the failed-to-qualify record (weight 40); in the knockout (stage 1) a club going through gets the qualification by round and one going out the knocked-out record (weight 50 to 100 over 3 rounds); the winner and the runner-up the final records'), ('wel_prm_cup_create_group_stage', 'WelPrmCup::create_group_stage', '0x928450', 'wel_prm_cup.cpp', 'thiscall, ret 4', 'regra: o segundo grupo (fase 0) tem 4 clubes, os inscritos 1, 3, 5 e 7 do bolo, numa fase de liga própria; depois a notícia do sorteio do grupo', 'rule: the second group (stage 0) has 4 clubs, entrants 1, 3, 5 and 7 of the pool, in a league stage of its own; then the group draw news')]
ESCAPADAS = {}  # nome: (explicação pt, explicação en), quando houver
tot, ac, esc, ok = cadeia(N)
assert ok, 'cadeia com divergência ou carreira que não chegou à data'
RES_PT, RES_EN = resultado_pt_en(N)
assert set(esc) <= set(ESCAPADAS), ('explicar as escapadas', esc)
lac_pt = ' '.join(f'`{e}` escapou: {ESCAPADAS[e][0]}.' for e in esc) + (' (lacuna em `PENDENCIAS.md`)' if esc else '')
lac_en = ' '.join(f'`{e}` escaped: {ESCAPADAS[e][1]}.' for e in esc) + (' (gap in `PENDENCIAS.en.md`)' if esc else '')
PS = prova_save(N)  # leva do save: mutações e prova pelo .qst gravado com e sem as rotinas (cadeia.sh)
VIA_PT = 'pela prova do save' if PS else 'pela carreira até 2002-06-01, confirmando no modo comparação as que escapam'
VIA_EN = 'by the save proof' if PS else 'by the career to 2002-06-01, confirming the escaped ones in comparison mode'
PS_PT = f'Prova do save (o .qst com e sem as rotinas): {PS}. ' if PS else ''
PS_EN = f'Save proof (the .qst with and without the routines): {PS.replace("IGUAL", "EQUAL").replace("DIFERENTE", "DIFFERENT")}. ' if PS else ''
M = (f"`mutacoes/leva{N}.py` ({tot}, {VIA_PT}): {ac} acusadas. {lac_pt} {PS_PT}"
     f"{RES_PT}")
ME = (f"`mutacoes/leva{N}.py` ({tot}, {VIA_EN}): {ac} caught. {lac_en} {PS_EN}"
      f"{RES_EN}")
fazer(N, 2421, 2421 + len(R), 'o calendário da Premier Division escocesa; a Premier Division escocesa: a virada, o dia e o split; a Copa da Liga escocesa: o construtor, as rodadas e o dia; a virada da Copa da Liga escocesa; a Copa da Liga galesa: o primeiro grupo, as regras e a passagem de fase; a Copa da Liga galesa: as honrarias, os registros dos técnicos e os grupos; a Copa Premier galesa: o primeiro grupo, as regras e a passagem de fase; a Copa Premier galesa: os registros dos técnicos e o segundo grupo', "the Scottish Premier Division schedule; the Scottish Premier Division: the turnover, the day update and the split; the Scottish League Cup: the constructor, the rounds and the day update; the Scottish League Cup turnover; the Welsh League Cup: the first group, the rules and the next stage; the Welsh League Cup: the honours, the managers' records and the groups; the Welsh Premier Cup: the first group, the rules and the next stage; the Welsh Premier Cup: the managers' records and the second group",
      [f"| `{a}()` | {e} | {c} | {f}: {d} |" for a, _, e, f, c, d, _ in R],
      [f"| `{a}()` | {e} | {c} | {f}: {d} |" for a, _, e, f, c, _, d in R],
      M, ME, [(a, g) for a, g, *_ in R], "'posicao_no_conteiner': 'position_in_container',", secao=('Simulação', 'Simulation'))
leia(N, 'o calendário da Premier Division escocesa; a Premier Division escocesa: a virada, o dia e o split; a Copa da Liga escocesa: o construtor, as rodadas e o dia; a virada da Copa da Liga escocesa; a Copa da Liga galesa: o primeiro grupo, as regras e a passagem de fase; a Copa da Liga galesa: as honrarias, os registros dos técnicos e os grupos; a Copa Premier galesa: o primeiro grupo, as regras e a passagem de fase; a Copa Premier galesa: os registros dos técnicos e o segundo grupo', "the Scottish Premier Division schedule; the Scottish Premier Division: the turnover, the day update and the split; the Scottish League Cup: the constructor, the rounds and the day update; the Scottish League Cup turnover; the Welsh League Cup: the first group, the rules and the next stage; the Welsh League Cup: the honours, the managers' records and the groups; the Welsh Premier Cup: the first group, the rules and the next stage; the Welsh Premier Cup: the managers' records and the second group", [(a, e, f + ', ' + c, dp, de) for a, _, e, f, c, dp, de in R], tot, ac, lac_pt, lac_en,
     campos=[], interessa=[])
